# How many offenders to name individually in the log. The count and the total
# are always exact (computed in the database); only the per-user list is
# capped, so a pathological number of offending rows can't build a
# multi-megabyte log string in the migration process's memory.
LOG_DETAIL_LIMIT = 100


def clamp_negative_balances(apps, schema_editor):
    Creator = apps.get_model('g12f', 'Creator')
    negative = Creator.objects.filter(tuzis__lt=0)

    # Aggregate in the database rather than pulling every row into Python.
    summary = negative.aggregate(n=Count('id'), total=Sum('tuzis'))
    count = summary['n'] or 0
    if not count:
        return

    sample = list(
        negative.order_by('tuzis')
        .values_list('id', 'username', 'tuzis')[:LOG_DETAIL_LIMIT]
    )
    detail = ", ".join(f"{u}(id={i}): {t}" for i, u, t in sample)
    if count > LOG_DETAIL_LIMIT:
        detail += f", ... and {count - LOG_DETAIL_LIMIT} more"
    message = (
        f"MONEY MIGRATION: forgiving {count} negative 2Z balance(s) "
        f"totalling {summary['total']} by clamping them to 0, so the "
        f"creator_tuzis_non_negative CHECK constraint can be added. "
        f"These users keep the overdraft. Worst offenders: {detail}"
    )
    # Both channels on purpose: the logger for structured collection, stdout so
    # it is impossible to miss in the Cloud Build deploy output. Forgiving real
    # (if small, and already spent) money is a decision, not a schema detail,
    # and it must not be able to happen quietly.
    logger.warning("%s", message)
    print(message)
    negative.update(tuzis=0)


